   402	    schemaVersion: 'lattice.managed_review_evidence_binding.v1',
   403	    runId: args.runId,
   404	    receiptId: args.receiptId,
   405	    proposalDigest: receipt?.evidenceProposalDigest ?? '',
   406	    terminalDigest: receipt?.terminalDigest ?? '',
   407	    importedAt: args.importedAt ?? new Date().toISOString(),
   408	    providerAgent: args.providerAgent,
   409	    providerHost: args.expected.providerHost,
   410	    lane: args.lane,
   411	    reviewRunId: args.reviewRunId,
   412	    headHash: args.expected.headHash,
   413	    materialHash: args.expected.materialHash,
   414	    storyFilesHash: args.expected.storyFilesHash,
   415	    promptHash: args.expected.promptHash,
   416	    envelopeId: args.expected.envelopeId,
   417	    managedPromptDigest: args.expected.managedPromptDigest,
